struct Point<T> {
    x: T,
    y: T,
}

impl<T> Point<T> {
    fn x(&self) -> &T {
        &self.x
    }
}

// only for Point<f64>: other Points do not have this method
impl Point<f64> {
    fn distance_from_origin(&self) -> f64 {
        (self.x.powi(2) + self.y.powi(2)).sqrt()
    }
}

fn main() {
    let p = Point { x: 3.0, y: 4.0 };
    println!("x = {}, distance = {}", p.x(), p.distance_from_origin());
    let q = Point { x: 3, y: 4 };
    println!("x = {}", q.x());
    // q.distance_from_origin(); // error: no method for Point<{integer}>
}

fn sum<const N: usize>(values: [i32; N]) -> i32 {
    let mut total = 0;
    for v in values {
        total += v;
    }
    total
}

struct Buffer<const N: usize> {
    data: [u8; N],
}

fn main() {
    println!("{}", sum([1, 2, 3]));
    println!("{}", sum([10; 5]));
    let b = Buffer::<4> { data: [0; 4] };
    println!("buffer of {} bytes", b.data.len());
}

struct Stack {
    items: Vec<i32>,
}

impl Stack {
    fn new() -> Self {
        Stack { items: Vec::new() }
    }
    fn push(&mut self, item: i32) {
        self.items.push(item);
    }
    fn len(&self) -> usize {
        self.items.len()
    }
    // fn peek(&self) -> Option<&T>
}

fn main() {
    let mut nums = Stack::new();
    nums.push(1);
    nums.push(3);
    println!("{:?}", nums.peek());

    let mut words = Stack::new();
    words.push("a");
    words.push("b");
    println!("{:?}", words.peek());
    println!("{}", words.len());
}
